// ─────────────────────────────────────────────────────────────────────────
//  03 · any vs all mask                                        ★★☆ core
//  concepts: mask semantics · vacuous empty mask
// ─────────────────────────────────────────────────────────────────────────
//
//  "Needs Write OR Delete" and "needs Write AND Delete" are different
//  checks — and an EMPTY mask makes the all-of check vacuously true.

using static Bootcamp.Check;

bool HasAny(Perm p, Perm mask)
{
    return (p & mask) != 0;
}

bool HasAll(Perm p, Perm mask)
{
    return (p & mask) == mask;
}

