exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · parse status safely                                    ★★☆ core
//  concepts: Enum.TryParse · Enum.IsDefined
// ─────────────────────────────────────────────────────────────────────────
//
//  `Enum.TryParse<OrderStatus>("99")` returns TRUE: any integer text
//  parses, and so does "paid,shipped". Wire input must name ONE
//  declared member.

using System.Globalization;
using static Bootcamp.Check;

OrderStatus? ParseStatus(string s)
{
    // a declared NUMBER: digits only, so no sign, no whitespace, no comma list
    if (s.Length > 0 && s.All(char.IsAsciiDigit))
        return int.TryParse(s, NumberStyles.None, CultureInfo.InvariantCulture, out var n) && Enum.IsDefined(typeof(OrderStatus), n)
            ? (OrderStatus)n
            : null;
    // an exact member NAME, any case; Enum.TryParse would also OR a comma list together
    foreach (var name in Enum.GetNames<OrderStatus>())
        if (string.Equals(name, s, StringComparison.OrdinalIgnoreCase))
            return Enum.Parse<OrderStatus>(name);
    return null;
}

