    Eq(ParseStatus("PENDING"), OrderStatus.Pending));

Test("\"99\" -> null (boundary: TryParse alone says true)", () =>
    Eq(ParseStatus("99"), null));

Test("\"2\" -> Shipped (a numeric value in range parses)", () =>
    Eq(ParseStatus("2"), OrderStatus.Shipped));

