// ─────────────────────────────────────────────────────────────────────────
//  05 · wire names                                             ★☆☆ warm-up
//  concepts: stable string contract · dictionary mapping
// ─────────────────────────────────────────────────────────────────────────
//
//  Renaming a C# member must never change the API. Wire strings are a
//  contract of their own: map them explicitly, both directions.

using static Bootcamp.Check;

var toWire = new Dictionary<OrderStatus, string>
{
    [OrderStatus.Pending] = "pending",
    [OrderStatus.Paid] = "paid",
    [OrderStatus.Shipped] = "shipped",
    [OrderStatus.Cancelled] = "cancelled",
};
var fromWire = toWire.ToDictionary(kv => kv.Value, kv => kv.Key);

string ToWire(OrderStatus s)
{
    return toWire[s];
}

OrderStatus FromWire(string s)
{
    if (fromWire.TryGetValue(s, out var status)) return status;
    throw new ArgumentException($"unknown status '{s}'");
}

