    foreach (var s in new[] { OrderStatus.Pending, OrderStatus.Paid, OrderStatus.Shipped, OrderStatus.Cancelled })
        Eq(FromWire(ToWire(s)), s);
});

Test("ToWire spells the contract strings", () =>
    Eq(new[] { ToWire(OrderStatus.Pending), ToWire(OrderStatus.Paid), ToWire(OrderStatus.Shipped), ToWire(OrderStatus.Cancelled) },
       new[] { "pending", "paid", "shipped", "cancelled" }));

Test("FromWire(\"paid\") -> Paid", () =>
