using static Bootcamp.Check;

List<string> ActiveNames(Perm p)
{
    var names = new List<string>();
    foreach (var f in new[] { Perm.Read, Perm.Write, Perm.Delete })
        if ((p & f) != 0) names.Add(f.ToString());
