exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  07 · count and single                                       ★★☆ core
//  concepts: popcount · power of two
// ─────────────────────────────────────────────────────────────────────────
//
//  How many rights does a mask hold, and is it exactly ONE right (an
//  API that takes "a permission" must reject a combination)?

using static Bootcamp.Check;

int FlagCount(Perm p)
{
    uint v = (uint)p;
    int count = 0;
    while (v != 0)
    {
        v &= v - 1;
        count++;
    }
    return count;
}

bool IsSingleRight(Perm p)
{
    uint v = (uint)p;
    return v != 0 && (v & (v - 1)) == 0;
}

