    Eq(FlagCount(Perm.None), 0));

Test("FlagCount(Read | Delete) -> 2", () =>
    Eq(FlagCount(Perm.Read | Perm.Delete), 2));

Test("IsSingleRight(Read) -> true", () =>
    Eq(IsSingleRight(Perm.Read), true));

Test("IsSingleRight(Admin) -> false", () =>
    Eq(IsSingleRight(Perm.Admin), false));

Test("IsSingleRight(None) -> false (boundary: zero is not a single right)", () =>
    Eq(IsSingleRight(Perm.None), false));

