exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  08 · role matrix                                            ★★★ stretch
//  concepts: composition · fail closed
// ─────────────────────────────────────────────────────────────────────────
//
//  Users carry role NAMES; a matrix maps roles to rights. Compute the
//  effective mask — and an unknown role must grant nothing.

using static Bootcamp.Check;

Perm Effective(List<string> roleNames, Dictionary<string, Perm> roles)
{
    var effective = Perm.None;
    foreach (var name in roleNames)
        if (roles.TryGetValue(name, out var granted))
            effective |= granted;
    return effective;
}

bool Authorize(List<string> roleNames, Dictionary<string, Perm> roles, Perm needed)
{
    var effective = Effective(roleNames, roles);
    return (effective & needed) == needed;
}

exercises.tests:
