    ["editor"] = Perm.Read | Perm.Write,
    ["owner"] = Perm.Admin,
};

Test("Effective([viewer, editor]) -> Read | Write", () =>
    Eq(Effective(["viewer", "editor"], Matrix()), Perm.Read | Perm.Write));

Test("Effective([ghost]) -> None (boundary: an unknown role grants nothing)", () =>
    Eq(Effective(["ghost"], Matrix()), Perm.None));

Test("Effective([]) -> None (boundary)", () =>
    Eq(Effective([], Matrix()), Perm.None));

Test("Authorize([editor], Read | Write) -> true", () =>
    Eq(Authorize(["editor"], Matrix(), Perm.Read | Perm.Write), true));

Test("Authorize([editor], Delete) -> false", () =>
    Eq(Authorize(["editor"], Matrix(), Perm.Delete), false));

Test("Authorize([viewer, owner], Admin) -> true", () =>
    Eq(Authorize(["viewer", "owner"], Matrix(), Perm.Admin), true));
